    def _type_check_with_pyright(
        cls, user_code: str, test_code: str
    ) -> "TypeCheckResult":

        combined_code = user_code + "\n" + test_code

        tokens = tokenize.generate_tokens(io.StringIO(combined_code).readline)
        error_lines = []
        for toknum, tokval, _, _, _ in tokens:
            if isinstance(tokval, str) and "# expect-type-error" in tokval:
                error_lines.append(tokval)

        error_reported = {}
        for line in error_lines:
            line_number = combined_code.find(line) + 1
            error_reported[line_number] = False

        result = subprocess.run(
            ["pyright", combined_code], capture_output=True, text=True
        )

        for line in result.stderr.splitlines():
            if "# expect-type-error" in line:
                line_number = combined_code.find(line) + 1
                error_reported[line_number] = True

        passed = all(value for value in error_reported.values())
        message = (
            "Type check passed" if passed else "Type check failed: expected type errors not reported"
        )

        return TypeCheckResult(message, passed)


class TypeCheckResult:
    def __init__(self, message: str, passed: bool):
        self.message = message
        self.passed = passed
